contract InvMutTest {
    C c;
    constructor() { c = new C(address(this), 0); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // We need to be able to receive Ether for sending wagers/donations
    receive() external payable {}

    // params: whale (address passed to constructor of C already), but we only need an amount to set bet limit and send wager
    // amount must be nonzero to be meaningful
    function run(uint256 newBetLimit, uint256 wagerAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (wagerAmount)); require(wagerAmount <= 1000000000000000000000000000000);
        require(newBetLimit > 0 && wagerAmount > 0);

        // Try to become owner operations: the deploying address of c is its owner; InvMutTest is not owner by default.
        // However the checker deploys a fresh C and passes it here; the constructor of C set owner to its deployer.
        // We cannot assume we are owner. So first, we conservatively try to call OpenToThePublic and AdjustBetAmounts and ignore revert status.
        bool opened;
        c.OpenToThePublic(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            opened = false;
        } else {
            opened = true;
        }

        // Try to set bet limit (may revert if not owner)
        bool betSet;
        c.AdjustBetAmounts(newBetLimit); bool __rev1 = __ESBMC_reverted(); if (__rev1) {
            betSet = false;
        } else {
            betSet = true;
        }

        // Ensure we have funds to attempt a wager: require this contract has balance >= wagerAmount
        require(address(this).balance >= wagerAmount, "need funds to wager");

        // Try to call wager() sending wagerAmount; record whether it reverted
        bool wagerReverted;
        c.wager{value: wagerAmount}(); bool __rev2 = __ESBMC_reverted(); if (__rev2) {
            wagerReverted = true;
        } else {
            wagerReverted = false;
        }

        // Observe hasPlayerWagered for this contract address
        bool recorded = c.hasPlayerWagered(address(this)); if (__ESBMC_reverted()) return;

        // General rule: If wager() did not revert, then the contract must record this test contract as having wagered (hasPlayerWagered == true).
        // If wager() reverted, then nothing is required about hasPlayerWagered. This asserts the implication.
        assert(wagerReverted || recorded);
    }
}

