// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PoCGame} from "../src/PoCGame.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PoCGame c;

    function setUp() public {
        c = new PoCGame(address(this), 0);
    }

    function _run(uint256 newBetLimit, uint256 wagerAmount) internal {
        wagerAmount = bound(wagerAmount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(newBetLimit > 0 && wagerAmount > 0);
        bool opened;
        try c.OpenToThePublic() {
            opened = true;
        } catch {
            opened = false;
        }
        bool betSet;
        try c.AdjustBetAmounts(newBetLimit) {
            betSet = true;
        } catch {
            betSet = false;
        }
        vm.assume(address(this).balance >= wagerAmount);
        bool wagerReverted;
        try c.wager{value: wagerAmount}() {
            wagerReverted = false;
        } catch {
            wagerReverted = true;
        }
        bool recorded;
        try c.hasPlayerWagered(address(this)) returns (bool __r) { recorded = __r; } catch { return; }
        assertTrue(wagerReverted || recorded);
    }

    function testFuzz_run(uint256 newBetLimit, uint256 wagerAmount) public {
        _run(newBetLimit, wagerAmount);
    }

    receive() external payable {}
}
